{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Trazodone, a high-transfer analogue with a chlorophenyl and basic amine motif, showed 72% absolute oral bioavailability in fasted women, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Linezolid, a morpholine-containing drug with high transfer relevance, had 100% absolute oral bioavailability in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Isoniazid showed 93% absolute oral bioavailability in fasted adult TB patients, a direct fasted-state measurement supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Imatinib, a high-transfer oral drug with a basic amine-containing scaffold, had approximately 98% absolute bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "A high-transfer analogue with a piperidine and aromatic system had 83% absolute bioavailability versus IV, indicating limited first-pass loss and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Molsidomine, despite extensive absorption considerations, had 44 ± 15% absolute bioavailability, still well above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "E4031, a high-transfer basic drug, had 92.2% absolute bioavailability in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "LY3000328, a morpholine-containing analogue, had oral bioavailability of at least 48.4–66.5%, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability values well above 20% (44–100%), including fasted-state measurements, so the query molecule is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule itself; prediction relies on high-transfer analogues.",
    "Fasted-state-specific absolute bioavailability data are available for only some analogues.",
    "A few records report bioavailability qualitatively or as minimum estimates rather than exact absolute F values."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

